from pathlib import Path
p=Path('app/AGENTS.md'); s=p.read_text(encoding='utf-8'); s+='\nMotion now drives page entrances and gallery crossfades. Project images open in an accessible modal viewer with next/previous, Escape, scroll lock, and opener focus restoration. TOC clicks must visibly highlight the destination heading after scrolling finishes; respect reduced motion with a static temporary highlight. Preserve the original portrait and SVG reveal.\n'; p.write_text(s,encoding='utf-8')
p=Path('DESIGN.md'); s=p.read_text(encoding='utf-8'); s+='\n## Motion and destination feedback — 27 October 2026\nMotion mini owns the established 650ms/100ms staggered entrances and temporary TOC heading feedback. TOC targets flash theme-aware navy/accent color after scrolling settles, then restore their underlying style; repeat clicks restart the feedback and reduced motion uses a static highlight. Motion for React owns gallery crossfades and the enlarged-image dialog. The native modal provides focus containment, Escape dismissal, scroll lock, keyboard arrows, and focus restoration. Preserve the existing portrait SVG sequence and all theme/Quick Access behavior.\n'; p.write_text(s,encoding='utf-8')
p=Path('README.md'); s=p.read_text(encoding='utf-8').replace('- Native Web Animations API for content entrances; IntersectionObserver for viewport reveals.','- Motion (mini engine) for content entrances and destination-heading highlights; IntersectionObserver for viewport reveals.\n- Motion for React for gallery crossfades and an enlarged-image viewer with keyboard controls.').replace('No extra animation framework is required. With `prefers-reduced-motion: reduce`, entrance effects are skipped and the portrait appears immediately.', 'Motion powers the shared animation system. With `prefers-reduced-motion: reduce`, entrance effects and gallery movement are skipped, the portrait appears immediately, and destination headings use a static temporary highlight.'); p.write_text(s,encoding='utf-8')
